+                if (string.Equals(property.Name, "label", StringComparison.OrdinalIgnoreCase))
+                {
+                    property.Value = StaticWebAsset.CombineNormalizedPaths("", newBasePath, property.Value, '/');
+                    endpoint.MarkProperiesAsModified();
+                }
+            }
+        }
+    }
